//! Differential ratchet for `src/engine/battleScriptCopyFoeStatsOpcode.ts`.
//! Expected complete projected outputs, typed controls, and exact ordered role
//! errors are generated by executing the canonical TypeScript opcode handler;
//! regenerate with `node --experimental-strip-types
//! core-rs/tools/gen-battle-script-copyfoestats-vectors.mjs`.

use std::collections::BTreeSet;

use factory_core::battle_script_copyfoestats::{
    apply_battle_script_copyfoestats, BattleScriptCopyFoeStatsBattlerState,
    BattleScriptCopyFoeStatsControl, BattleScriptCopyFoeStatsOutcome,
    BattleScriptCopyFoeStatsRoles, BattleScriptCopyFoeStatsRules,
    BATTLE_SCRIPT_COPYFOESTATS_BATTLERS, BATTLE_SCRIPT_COPYFOESTATS_BATTLER_COUNT,
    BATTLE_SCRIPT_COPYFOESTATS_NEUTRAL_STAT_STAGE, BATTLE_SCRIPT_COPYFOESTATS_STAT_STAGE_COUNT,
};
use factory_core::battle_script_copyfoestats_vectors_gen::{
    BattleScriptCopyFoeStatsVectorCase, BattleScriptCopyFoeStatsVectorState,
    BATTLE_SCRIPT_COPYFOESTATS_ATTACKER_DOMAIN, BATTLE_SCRIPT_COPYFOESTATS_BRANCH_CENSUS,
    BATTLE_SCRIPT_COPYFOESTATS_CANONICAL_INVALID_S8_PROBES, BATTLE_SCRIPT_COPYFOESTATS_CASES,
    BATTLE_SCRIPT_COPYFOESTATS_CATEGORY_CENSUS, BATTLE_SCRIPT_COPYFOESTATS_DOMAIN_CENSUS,
    BATTLE_SCRIPT_COPYFOESTATS_FULL_DOMAIN_ROLE_PAIR,
    BATTLE_SCRIPT_COPYFOESTATS_MIXED_STAGE_EDGE_DOMAIN, BATTLE_SCRIPT_COPYFOESTATS_SIGNED_S8_MAX,
    BATTLE_SCRIPT_COPYFOESTATS_SIGNED_S8_MIN, BATTLE_SCRIPT_COPYFOESTATS_SIGNED_S8_VALUE_COUNT,
    BATTLE_SCRIPT_COPYFOESTATS_STAT_POSITION_DOMAIN, BATTLE_SCRIPT_COPYFOESTATS_TARGET_DOMAIN,
    BATTLE_SCRIPT_COPYFOESTATS_VECTOR_CORPUS_SHA256,
};

fn rules(value: BattleScriptCopyFoeStatsVectorState) -> BattleScriptCopyFoeStatsRules {
    BattleScriptCopyFoeStatsRules {
        battlers: value
            .stat_stages
            .map(|stat_stages| BattleScriptCopyFoeStatsBattlerState { stat_stages }),
        selector_roles: BattleScriptCopyFoeStatsRoles {
            attacker: value.attacker,
            target: value.target,
        },
    }
}

fn vector_state(value: BattleScriptCopyFoeStatsRules) -> BattleScriptCopyFoeStatsVectorState {
    BattleScriptCopyFoeStatsVectorState {
        stat_stages: value.battlers.map(|battler| battler.stat_stages),
        attacker: value.selector_roles.attacker,
        target: value.selector_roles.target,
    }
}

#[test]
fn complete_projected_outputs_controls_exact_ordered_errors_and_input_preservation_match_canonical_typescript(
) {
    assert_eq!(BATTLE_SCRIPT_COPYFOESTATS_CASES.len(), 2075);
    for (case_index, case) in BATTLE_SCRIPT_COPYFOESTATS_CASES.iter().enumerate() {
        execute_case(case_index, case);
    }
}

fn execute_case(case_index: usize, case: &BattleScriptCopyFoeStatsVectorCase) {
    let input = rules(case.initial);
    let before = input;
    let mut current = input;
    let mut actual_controls = Vec::new();
    let mut actual_error = None;

    for application in 0..case.applications {
        let prior = current;
        match apply_battle_script_copyfoestats(&current) {
            Ok(outcome) => {
                actual_controls.push(outcome.control);
                assert_transition_shape(case_index, case, application, prior, outcome);
                current = outcome.rules;
            }
            Err(error) => {
                actual_error = Some(error.to_string());
                break;
            }
        }
    }

    assert_eq!(
        input, before,
        "case {case_index} {}: native transformation mutated input",
        case.label,
    );
    match (actual_error, case.expected, case.expected_error) {
        (None, Some(expected), None) => {
            assert_eq!(
                actual_controls.as_slice(),
                case.controls,
                "case {case_index} {}: canonical control sequence",
                case.label,
            );
            assert_eq!(
                actual_controls.len(),
                usize::from(case.applications),
                "case {case_index} {}: successful sequence stopped early",
                case.label,
            );
            assert_eq!(
                vector_state(current),
                expected,
                "case {case_index} {}: complete projected output",
                case.label,
            );
        }
        (Some(error), None, Some(expected_error)) => {
            assert_eq!(
                actual_controls.as_slice(),
                case.controls,
                "case {case_index} {}: error must not produce a control result",
                case.label,
            );
            assert_eq!(
                error, expected_error,
                "case {case_index} {}: exact canonical role error",
                case.label,
            );
        }
        (error, expected, expected_error) => panic!(
            "case {case_index} {}: generated outcome shape disagrees with native result: error={error:?}, expected={expected:?}, expected_error={expected_error:?}",
            case.label,
        ),
    }
}

fn assert_transition_shape(
    case_index: usize,
    case: &BattleScriptCopyFoeStatsVectorCase,
    application: u8,
    prior: BattleScriptCopyFoeStatsRules,
    outcome: BattleScriptCopyFoeStatsOutcome,
) {
    assert_eq!(
        outcome.control,
        BattleScriptCopyFoeStatsControl::Advance,
        "case {case_index} {} application {application}: Psych Up must advance",
        case.label,
    );
    let attacker = prior.selector_roles.attacker.unwrap_or_else(|| {
        panic!(
            "case {case_index} {} application {application}: advance had no attacker",
            case.label,
        )
    });
    let target = prior.selector_roles.target.unwrap_or_else(|| {
        panic!(
            "case {case_index} {} application {application}: advance had no target",
            case.label,
        )
    });

    assert_eq!(
        outcome.rules.selector_roles, prior.selector_roles,
        "case {case_index} {} application {application}: changed role bindings",
        case.label,
    );
    assert_eq!(
        outcome.rules.battlers[attacker.index()].stat_stages,
        prior.battlers[target.index()].stat_stages,
        "case {case_index} {} application {application}: attacker did not receive all target stages",
        case.label,
    );
    for battler in BATTLE_SCRIPT_COPYFOESTATS_BATTLERS {
        if battler != attacker {
            assert_eq!(
                outcome.rules.battlers[battler.index()],
                prior.battlers[battler.index()],
                "case {case_index} {} application {application}: changed sibling battler {}",
                case.label,
                battler.as_u8(),
            );
        }
    }
    if attacker == target {
        assert_eq!(
            outcome.rules, prior,
            "case {case_index} {} application {application}: self-copy changed narrow state",
            case.label,
        );
    }
}

#[test]
fn one_non_alias_pair_exhaustively_covers_every_signed_s8_value_at_every_stage_position() {
    let full_domain = BATTLE_SCRIPT_COPYFOESTATS_CASES
        .iter()
        .filter(|case| case.category == "non-alias-stage-position-signed-s8-full-domain")
        .collect::<Vec<_>>();
    assert_eq!(full_domain.len(), 2048);

    let (full_attacker, full_target) = BATTLE_SCRIPT_COPYFOESTATS_FULL_DOMAIN_ROLE_PAIR;
    assert_ne!(full_attacker, full_target);
    let observed = full_domain
        .iter()
        .map(|case| {
            let attacker = case
                .initial
                .attacker
                .unwrap_or_else(|| panic!("full-domain case {} lacks attacker", case.label));
            let target = case
                .initial
                .target
                .unwrap_or_else(|| panic!("full-domain case {} lacks target", case.label));
            assert_eq!(attacker.as_u8(), full_attacker);
            assert_eq!(target.as_u8(), full_target);
            let position = case
                .targeted_stat
                .unwrap_or_else(|| panic!("full-domain case {} lacks target position", case.label));
            let target_value = case.initial.stat_stages[target.index()][usize::from(position)];
            assert_ne!(
                case.initial.stat_stages[attacker.index()][usize::from(position)],
                target_value,
                "{}: exhaustive copy cell must begin distinct",
                case.label,
            );
            assert_eq!(
                case.expected
                    .expect("full-domain expected output")
                    .stat_stages[attacker.index()],
                case.initial.stat_stages[target.index()],
                "{}: generated output did not copy the entire target row",
                case.label,
            );
            (position, target_value)
        })
        .collect::<BTreeSet<_>>();
    let expected = BATTLE_SCRIPT_COPYFOESTATS_STAT_POSITION_DOMAIN
        .into_iter()
        .flat_map(|position| {
            (BATTLE_SCRIPT_COPYFOESTATS_SIGNED_S8_MIN..=BATTLE_SCRIPT_COPYFOESTATS_SIGNED_S8_MAX)
                .map(move |value| (position, value))
        })
        .collect::<BTreeSet<_>>();
    assert_eq!(observed, expected);
}

#[test]
fn compact_mixed_boundary_matrix_covers_all_sixteen_role_pairs_without_cartesian_expansion() {
    let pair_matrix = BATTLE_SCRIPT_COPYFOESTATS_CASES
        .iter()
        .filter(|case| case.category == "attacker-target-pair-mixed-boundary-matrix")
        .collect::<Vec<_>>();
    assert_eq!(pair_matrix.len(), 16);
    let expected_pairs = BATTLE_SCRIPT_COPYFOESTATS_ATTACKER_DOMAIN
        .into_iter()
        .flat_map(|attacker| {
            BATTLE_SCRIPT_COPYFOESTATS_TARGET_DOMAIN
                .into_iter()
                .map(move |target| (attacker, target))
        })
        .collect::<BTreeSet<_>>();
    let observed_pairs = pair_matrix
        .iter()
        .map(|case| {
            let attacker = case.initial.attacker.expect("pair-matrix attacker");
            let target = case.initial.target.expect("pair-matrix target");
            let target_values = case.initial.stat_stages[target.index()]
                .into_iter()
                .collect::<BTreeSet<_>>();
            assert_eq!(
                target_values,
                BATTLE_SCRIPT_COPYFOESTATS_MIXED_STAGE_EDGE_DOMAIN
                    .into_iter()
                    .collect::<BTreeSet<_>>(),
                "{}: target row lost a mixed signed boundary",
                case.label,
            );
            assert_eq!(
                case.expected
                    .expect("pair-matrix expected output")
                    .stat_stages[attacker.index()],
                case.initial.stat_stages[target.index()],
                "{}: pair matrix did not copy entire target row",
                case.label,
            );
            (attacker.as_u8(), target.as_u8())
        })
        .collect::<BTreeSet<_>>();
    assert_eq!(observed_pairs, expected_pairs);
    assert_eq!(
        observed_pairs
            .iter()
            .filter(|(attacker, target)| attacker == target)
            .count(),
        4,
        "the full role matrix must retain all four alias pairs",
    );
}

#[test]
fn ordered_missing_roles_siblings_neutral_alias_and_repeated_copy_boundaries_are_pinned() {
    let ordered_errors = BATTLE_SCRIPT_COPYFOESTATS_CASES
        .iter()
        .filter(|case| case.category == "ordered-missing-role-errors")
        .collect::<Vec<_>>();
    assert_eq!(ordered_errors.len(), 3);
    let both_missing = ordered_errors
        .iter()
        .find(|case| case.label == "missing_attacker_and_target_roles_attacker_error_first")
        .expect("both-missing vector");
    assert_eq!(both_missing.initial.attacker, None);
    assert_eq!(both_missing.initial.target, None);
    assert_eq!(both_missing.expected, None);
    assert_eq!(both_missing.controls, &[]);
    assert_eq!(
        both_missing.expected_error,
        Some("B_SCR_OP_COPYFOESTATS requires an attacker role"),
    );
    let missing_attacker = ordered_errors
        .iter()
        .find(|case| case.label == "missing_attacker_role_precedes_target_stage_read")
        .expect("missing-attacker vector");
    assert_eq!(missing_attacker.initial.attacker, None);
    assert_eq!(
        missing_attacker.initial.target.map(|value| value.as_u8()),
        Some(3)
    );
    assert_eq!(
        missing_attacker.expected_error,
        Some("B_SCR_OP_COPYFOESTATS requires an attacker role"),
    );
    let missing_target = ordered_errors
        .iter()
        .find(|case| case.label == "missing_target_role_after_attacker_resolution")
        .expect("missing-target vector");
    assert_eq!(
        missing_target.initial.attacker.map(|value| value.as_u8()),
        Some(2)
    );
    assert_eq!(missing_target.initial.target, None);
    assert_eq!(
        missing_target.expected_error,
        Some("B_SCR_OP_COPYFOESTATS requires a target role"),
    );

    let siblings = BATTLE_SCRIPT_COPYFOESTATS_CASES
        .iter()
        .filter(|case| case.category == "sibling-preservation")
        .collect::<Vec<_>>();
    assert_eq!(siblings.len(), 4);
    assert_eq!(
        siblings
            .iter()
            .map(|case| {
                case.initial
                    .attacker
                    .expect("sibling case attacker")
                    .as_u8()
            })
            .collect::<BTreeSet<_>>(),
        BATTLE_SCRIPT_COPYFOESTATS_ATTACKER_DOMAIN
            .into_iter()
            .collect::<BTreeSet<_>>(),
    );
    for case in siblings {
        let attacker = case.initial.attacker.expect("sibling case attacker");
        let target = case.initial.target.expect("sibling case target");
        assert_ne!(attacker, target);
        let expected = case.expected.expect("sibling case expected output");
        assert_eq!(
            expected.attacker, case.initial.attacker,
            "{}: attacker role changed",
            case.label
        );
        assert_eq!(
            expected.target, case.initial.target,
            "{}: target role changed",
            case.label
        );
        for battler in BATTLE_SCRIPT_COPYFOESTATS_BATTLERS {
            if battler != attacker {
                assert_eq!(
                    expected.stat_stages[battler.index()],
                    case.initial.stat_stages[battler.index()],
                    "{}: sibling {} changed",
                    case.label,
                    battler.as_u8(),
                );
            }
        }
    }

    for label in [
        "neutral_non_alias_rows_copy_and_advance",
        "neutral_alias_rows_copy_and_advance",
    ] {
        let neutral = BATTLE_SCRIPT_COPYFOESTATS_CASES
            .iter()
            .find(|case| case.label == label)
            .expect("neutral vector");
        assert_eq!(neutral.branch, "advance");
        assert_eq!(
            neutral.controls,
            &[BattleScriptCopyFoeStatsControl::Advance]
        );
        assert_eq!(neutral.expected, Some(neutral.initial));
        assert_eq!(
            neutral.initial.stat_stages,
            [[BATTLE_SCRIPT_COPYFOESTATS_NEUTRAL_STAT_STAGE; 8]; 4],
        );
    }
    let alias = BATTLE_SCRIPT_COPYFOESTATS_CASES
        .iter()
        .find(|case| case.label == "mixed_alias_row_copies_self_and_advances")
        .expect("mixed-alias vector");
    assert_eq!(alias.initial.attacker.map(|value| value.as_u8()), Some(3));
    assert_eq!(alias.initial.target.map(|value| value.as_u8()), Some(3));
    assert_eq!(alias.expected, Some(alias.initial));

    let repeated = BATTLE_SCRIPT_COPYFOESTATS_CASES
        .iter()
        .find(|case| {
            case.label == "repeated_non_alias_copy_is_value_idempotent_and_advances_each_time"
        })
        .expect("repeated-copy vector");
    assert_eq!(repeated.applications, 2);
    assert_eq!(repeated.branch, "advance-then-advance");
    assert_eq!(
        repeated.controls,
        &[
            BattleScriptCopyFoeStatsControl::Advance,
            BattleScriptCopyFoeStatsControl::Advance,
        ],
    );
    let attacker = repeated.initial.attacker.expect("repeated attacker");
    let target = repeated.initial.target.expect("repeated target");
    let mut first_copy = repeated.initial;
    first_copy.stat_stages[attacker.index()] = repeated.initial.stat_stages[target.index()];
    assert_eq!(repeated.expected, Some(first_copy));
}

#[test]
fn fixed_domains_censuses_hash_and_bounded_corpus_shape_are_ratchet_pinned() {
    assert_eq!(BATTLE_SCRIPT_COPYFOESTATS_BATTLER_COUNT, 4);
    assert_eq!(BATTLE_SCRIPT_COPYFOESTATS_STAT_STAGE_COUNT, 8);
    assert_eq!(BATTLE_SCRIPT_COPYFOESTATS_NEUTRAL_STAT_STAGE, 6);
    assert_eq!(
        BATTLE_SCRIPT_COPYFOESTATS_BATTLERS.map(|battler| battler.as_u8()),
        BATTLE_SCRIPT_COPYFOESTATS_ATTACKER_DOMAIN,
    );
    assert_eq!(BATTLE_SCRIPT_COPYFOESTATS_ATTACKER_DOMAIN, [0, 1, 2, 3]);
    assert_eq!(BATTLE_SCRIPT_COPYFOESTATS_TARGET_DOMAIN, [0, 1, 2, 3]);
    assert_eq!(
        BATTLE_SCRIPT_COPYFOESTATS_STAT_POSITION_DOMAIN,
        [0, 1, 2, 3, 4, 5, 6, 7],
    );
    assert_eq!(BATTLE_SCRIPT_COPYFOESTATS_SIGNED_S8_MIN, -128);
    assert_eq!(BATTLE_SCRIPT_COPYFOESTATS_SIGNED_S8_MAX, 127);
    assert_eq!(BATTLE_SCRIPT_COPYFOESTATS_SIGNED_S8_VALUE_COUNT, 256);
    assert_eq!(
        BATTLE_SCRIPT_COPYFOESTATS_CANONICAL_INVALID_S8_PROBES,
        [-129, 128],
    );
    assert_eq!(
        BATTLE_SCRIPT_COPYFOESTATS_MIXED_STAGE_EDGE_DOMAIN,
        [-128, -127, -1, 0, 1, 6, 42, 127],
    );
    assert_eq!(BATTLE_SCRIPT_COPYFOESTATS_FULL_DOMAIN_ROLE_PAIR, (0, 1));
    assert_eq!(
        BATTLE_SCRIPT_COPYFOESTATS_DOMAIN_CENSUS,
        [
            ("battler-slots", 4),
            ("stat-stage-cells-per-battler", 8),
            ("signed-s8-values", 256),
            ("mixed-boundary-stage-values", 8),
            ("attacker-role-values", 4),
            ("target-role-values", 4),
            ("complete-attacker-target-role-pairs", 16),
            ("exhaustive-non-alias-role-pairs", 1),
            ("exhaustive-non-alias-stage-position-value-cases", 2048),
            (
                "full-16-pair-stage-position-value-cartesian-cases-intentionally-omitted",
                32768,
            ),
            ("typed-ordered-missing-role-cases", 3),
            ("application-count-values", 2),
            ("ignored-failure-pointer-fields-in-projection", 0),
            ("absolute-program-counter-fields-in-projection", 0),
            ("abi-exports-added", 0),
            ("unsupported-barriers-added", 0),
            ("generated-file-byte-limit-exclusive", 5_000_000),
        ],
    );
    assert_eq!(
        BATTLE_SCRIPT_COPYFOESTATS_CATEGORY_CENSUS,
        [
            ("attacker-target-pair-mixed-boundary-matrix", 16),
            ("neutral-and-alias-success", 3),
            ("non-alias-stage-position-signed-s8-full-domain", 2048),
            ("ordered-missing-role-errors", 3),
            ("repeated-copy-idempotence", 1),
            ("sibling-preservation", 4),
        ],
    );
    assert_eq!(
        BATTLE_SCRIPT_COPYFOESTATS_BRANCH_CENSUS,
        [
            ("advance", 2071),
            ("advance-then-advance", 1),
            ("missing-attacker-role", 2),
            ("missing-target-role", 1),
        ],
    );
    assert_eq!(
        BATTLE_SCRIPT_COPYFOESTATS_VECTOR_CORPUS_SHA256,
        "e1f1cb9ea7e97c5536fd9b0ebecfa2512e5ec12da6356a24e550762feaf570f9",
    );
}
